import java.util.*;
class Solution {
Node cloneGraph(Node node){return clone(node,new IdentityHashMap<>());} Node clone(Node n,Map<Node,Node> map){if(n==null)return null;if(map.containsKey(n))return map.get(n);Node c=new Node(n.val);map.put(n,c);for(Node v:n.neighbors)c.neighbors.add(clone(v,map));return c;}
String alienOrder(String[] words){Map<Character,Set<Character>> adj=new TreeMap<>();Map<Character,Integer> deg=new TreeMap<>();for(String s:words)for(char c:s.toCharArray()){adj.putIfAbsent(c,new HashSet<>());deg.put(c,0);}for(int i=1;i<words.length;i++){String a=words[i-1],b=words[i];int j=0;while(j<Math.min(a.length(),b.length())&&a.charAt(j)==b.charAt(j))j++;if(j==b.length()&&a.length()>b.length())return "";if(j<Math.min(a.length(),b.length())&&adj.get(a.charAt(j)).add(b.charAt(j)))deg.put(b.charAt(j),deg.get(b.charAt(j))+1);}Queue<Character> q=new ArrayDeque<>();for(char c:deg.keySet())if(deg.get(c)==0)q.add(c);StringBuilder out=new StringBuilder();while(!q.isEmpty()){char c=q.remove();out.append(c);for(char v:adj.get(c)){deg.put(v,deg.get(v)-1);if(deg.get(v)==0)q.add(v);}}return out.length()==deg.size()?out.toString():"";}
ListNode reverseList(ListNode head){ListNode prev=null;while(head!=null){ListNode next=head.next;head.next=prev;prev=head;head=next;}return prev;}
boolean hasCycle(ListNode head){Set<ListNode> seen=Collections.newSetFromMap(new IdentityHashMap<>());while(head!=null){if(!seen.add(head))return true;head=head.next;}return false;}
ListNode mergeTwoLists(ListNode a,ListNode b){ListNode dummy=new ListNode(0),t=dummy;while(a!=null&&b!=null){if(a.val<=b.val){t.next=a;a=a.next;}else{t.next=b;b=b.next;}t=t.next;}t.next=a!=null?a:b;return dummy.next;}
ListNode mergeKLists(ListNode[] lists){ListNode out=null;for(ListNode n:lists)out=mergeTwoLists(out,n);return out;}
ListNode removeNthFromEnd(ListNode head,int n){ListNode dummy=new ListNode(0,head),a=dummy,b=dummy;for(int i=0;i<=n;i++)b=b.next;while(b!=null){a=a.next;b=b.next;}a.next=a.next.next;return dummy.next;}
void reorderList(ListNode head){List<ListNode> a=new ArrayList<>(),out=new ArrayList<>();for(ListNode p=head;p!=null;p=p.next)a.add(p);int l=0,r=a.size()-1;while(l<=r){out.add(a.get(l++));if(l<=r)out.add(a.get(r--));}for(int i=0;i<out.size();i++)out.get(i).next=i+1<out.size()?out.get(i+1):null;}
List<List<String>> groupAnagrams(String[] strs){Map<String,List<String>> m=new HashMap<>();for(String s:strs){char[] a=s.toCharArray();Arrays.sort(a);m.computeIfAbsent(new String(a),k->new ArrayList<>()).add(s);}return new ArrayList<>(m.values());}
int maxDepth(TreeNode root){return root==null?0:1+Math.max(maxDepth(root.left),maxDepth(root.right));}
boolean isSameTree(TreeNode p,TreeNode q){return p!=null&&q!=null?p.val==q.val&&isSameTree(p.left,q.left)&&isSameTree(p.right,q.right):p==q;}
TreeNode invertTree(TreeNode root){if(root!=null){TreeNode l=invertTree(root.left);root.left=invertTree(root.right);root.right=l;}return root;}
int maxPathSum(TreeNode root){int[] best={Integer.MIN_VALUE};gain(root,best);return best[0];}int gain(TreeNode n,int[] best){if(n==null)return 0;int a=Math.max(0,gain(n.left,best)),b=Math.max(0,gain(n.right,best));best[0]=Math.max(best[0],n.val+a+b);return n.val+Math.max(a,b);}
int[][] levelOrder(TreeNode root){List<List<Integer>> out=new ArrayList<>();level(root,0,out);return out.stream().map(row->row.stream().mapToInt(Integer::intValue).toArray()).toArray(int[][]::new);}void level(TreeNode n,int d,List<List<Integer>> out){if(n==null)return;if(out.size()==d)out.add(new ArrayList<>());out.get(d).add(n.val);level(n.left,d+1,out);level(n.right,d+1,out);}
boolean isSubtree(TreeNode root,TreeNode subRoot){return root!=null&&(isSameTree(root,subRoot)||isSubtree(root.left,subRoot)||isSubtree(root.right,subRoot));}
TreeNode buildTree(int[] preorder,int[] inorder){return build(preorder,inorder,new int[]{0},0,inorder.length);}TreeNode build(int[] p,int[] in,int[] at,int l,int r){if(l>=r)return null;int v=p[at[0]++],j=l;while(in[j]!=v)j++;return new TreeNode(v,build(p,in,at,l,j),build(p,in,at,j+1,r));}
boolean isValidBST(TreeNode root){return valid(root,Long.MIN_VALUE,Long.MAX_VALUE);}boolean valid(TreeNode n,long lo,long hi){return n==null||(lo<n.val&&n.val<hi&&valid(n.left,lo,n.val)&&valid(n.right,n.val,hi));}
int kthSmallest(TreeNode root,int k){List<Integer> a=new ArrayList<>();inorder(root,a);return a.get(k-1);}void inorder(TreeNode n,List<Integer> a){if(n!=null){inorder(n.left,a);a.add(n.val);inorder(n.right,a);}}
TreeNode lowestCommonAncestor(TreeNode root,TreeNode p,TreeNode q){while(root!=null){if(Math.max(p.val,q.val)<root.val)root=root.left;else if(Math.min(p.val,q.val)>root.val)root=root.right;else return root;}return null;}
String[] findWords(char[][] board,String[] words){Set<String> out=new HashSet<>();for(String w:words){boolean found=false;for(int r=0;r<board.length;r++)for(int c=0;c<board[r].length;c++)found=found||word(board,w,r,c,0);if(found)out.add(w);}return out.toArray(String[]::new);}boolean word(char[][] a,String s,int r,int c,int i){if(i==s.length())return true;if(r<0||c<0||r>=a.length||c>=a[0].length||a[r][c]!=s.charAt(i))return false;char x=a[r][c];a[r][c]=0;boolean ok=word(a,s,r+1,c,i+1)||word(a,s,r-1,c,i+1)||word(a,s,r,c+1,i+1)||word(a,s,r,c-1,i+1);a[r][c]=x;return ok;}
}
class StringCodec{String encode(String[] strs){StringBuilder b=new StringBuilder();for(String s:strs)b.append(s.length()).append('#').append(s);return b.toString();}String[] decode(String data){List<String> out=new ArrayList<>();int i=0;while(i<data.length()){int j=data.indexOf('#',i),n=Integer.parseInt(data.substring(i,j));out.add(data.substring(j+1,j+1+n));i=j+1+n;}return out.toArray(String[]::new);}}
class TreeCodec{String serialize(TreeNode root){return root==null?"#,":root.val+","+serialize(root.left)+serialize(root.right);}TreeNode deserialize(String data){return read(data.split(","),new int[]{0});}TreeNode read(String[] a,int[] at){String s=a[at[0]++];if(s.equals("#"))return null;return new TreeNode(Integer.parseInt(s),read(a,at),read(a,at));}}
class Trie{Set<String> words=new HashSet<>();void insert(String word){words.add(word);}boolean search(String word){return words.contains(word);}boolean startsWith(String prefix){return words.stream().anyMatch(s->s.startsWith(prefix));}}
class WordDictionary{Set<String> words=new HashSet<>();void addWord(String word){words.add(word);}boolean search(String p){for(String s:words){if(s.length()!=p.length())continue;boolean ok=true;for(int i=0;i<p.length();i++)if(p.charAt(i)!='.'&&p.charAt(i)!=s.charAt(i))ok=false;if(ok)return true;}return false;}}
class MedianFinder{List<Integer> a=new ArrayList<>();void addNum(int num){a.add(num);}double findMedian(){Collections.sort(a);int m=a.size()/2;return a.size()%2==1?a.get(m):((double)a.get(m-1)+a.get(m))/2;}}
